// =====================================================================
// Generates src/models/pecan_tree.glb - a small low-poly tree for the 3D farm.
//   brown 6-sided trunk + a crown of 3 faceted green "blobs"
//   (flat-shaded icospheres in slightly different greens)
// Units are metres; the model's base sits at height 0.
//
// Run:  node server/make_tree_model.js
// Generated by our team, so there is no licence to credit.
// =====================================================================
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const OUT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "models", "pecan_tree.glb");

// ---------- tree shape (metres) ----------
const TRUNK = { radius: 0.28, height: 2.6, sides: 6 };
const CROWN = [                                   // [x, y(up), z, radius, colour]
  [0.0, 4.6, 0.0, 2.6, [0.24, 0.47, 0.18]],
  [1.0, 3.9, 0.6, 1.9, [0.30, 0.54, 0.21]],
  [-0.9, 4.0, -0.7, 2.0, [0.20, 0.42, 0.15]],
];
const TRUNK_COLOUR = [0.36, 0.25, 0.16];

// ---------- geometry helpers (flat shading: every triangle gets its own vertices) ----------
function addTriangle(mesh, a, b, c) {
  const u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
  const v = [c[0] - a[0], c[1] - a[1], c[2] - a[2]];
  let n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
  const len = Math.hypot(...n) || 1;
  n = n.map((x) => x / len);
  for (const p of [a, b, c]) {
    mesh.positions.push(...p);
    mesh.normals.push(...n);
    mesh.indices.push(mesh.indices.length);
  }
}

function trunk(mesh) {
  const { radius: r, height: h, sides } = TRUNK;
  const ring = (y, rr) => Array.from({ length: sides }, (_, i) => {
    const t = (i / sides) * Math.PI * 2;
    return [rr * Math.cos(t), y, rr * Math.sin(t)];
  });
  const bottom = ring(0, r), top = ring(h, r * 0.75);
  for (let i = 0; i < sides; i++) {
    const j = (i + 1) % sides;
    addTriangle(mesh, bottom[i], top[i], bottom[j]);
    addTriangle(mesh, bottom[j], top[i], top[j]);
  }
}

// icosphere, 1 subdivision (80 faces), slightly jittered so it looks hand-made
function blob(mesh, cx, cy, cz, radius, seed) {
  const t = (1 + Math.sqrt(5)) / 2;
  let verts = [[-1, t, 0], [1, t, 0], [-1, -t, 0], [1, -t, 0], [0, -1, t], [0, 1, t], [0, -1, -t], [0, 1, -t],
               [t, 0, -1], [t, 0, 1], [-t, 0, -1], [-t, 0, 1]].map((v) => { const l = Math.hypot(...v); return v.map((x) => x / l); });
  let faces = [[0, 11, 5], [0, 5, 1], [0, 1, 7], [0, 7, 10], [0, 10, 11], [1, 5, 9], [5, 11, 4], [11, 10, 2], [10, 7, 6], [7, 1, 8],
               [3, 9, 4], [3, 4, 2], [3, 2, 6], [3, 6, 8], [3, 8, 9], [4, 9, 5], [2, 4, 11], [6, 2, 10], [8, 6, 7], [9, 8, 1]];
  const cache = {};
  const mid = (a, b) => {
    const key = a < b ? `${a}_${b}` : `${b}_${a}`;
    if (cache[key] === undefined) {
      const m = verts[a].map((x, i) => (x + verts[b][i]) / 2);
      const l = Math.hypot(...m);
      verts.push(m.map((x) => x / l));
      cache[key] = verts.length - 1;
    }
    return cache[key];
  };
  faces = faces.flatMap(([a, b, c]) => { const ab = mid(a, b), bc = mid(b, c), ca = mid(c, a); return [[a, ab, ca], [b, bc, ab], [c, ca, bc], [ab, bc, ca]]; });

  let s = seed;
  const rand = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
  const pts = verts.map((v) => {
    const k = radius * (0.88 + rand() * 0.24);              // bumpy crown
    return [cx + v[0] * k, cy + v[1] * k * 0.85, cz + v[2] * k];   // a bit flattened
  });
  for (const [a, b, c] of faces) addTriangle(mesh, pts[a], pts[b], pts[c]);
}

// ---------- build the meshes ----------
const parts = [];
const trunkMesh = { positions: [], normals: [], indices: [], colour: TRUNK_COLOUR };
trunk(trunkMesh);
parts.push(trunkMesh);
CROWN.forEach(([x, y, z, r, colour], i) => {
  const m = { positions: [], normals: [], indices: [], colour };
  blob(m, x, y, z, r, 1234 + i * 977);
  parts.push(m);
});

// ---------- write glTF 2.0 binary (.glb) ----------
const buffers = [];
let offset = 0;
const bufferViews = [], accessors = [], materials = [], primitives = [];

function addView(typedArray, target) {
  const buf = Buffer.from(typedArray.buffer, typedArray.byteOffset, typedArray.byteLength);
  const pad = (4 - (buf.length % 4)) % 4;
  buffers.push(buf, Buffer.alloc(pad));
  bufferViews.push({ buffer: 0, byteOffset: offset, byteLength: buf.length, target });
  offset += buf.length + pad;
  return bufferViews.length - 1;
}

for (const p of parts) {
  const pos = new Float32Array(p.positions), nor = new Float32Array(p.normals), idx = new Uint16Array(p.indices);
  const min = [0, 1, 2].map((k) => Math.min(...p.positions.filter((_, i) => i % 3 === k)));
  const max = [0, 1, 2].map((k) => Math.max(...p.positions.filter((_, i) => i % 3 === k)));
  accessors.push({ bufferView: addView(pos, 34962), componentType: 5126, count: pos.length / 3, type: "VEC3", min, max });
  const posAcc = accessors.length - 1;
  accessors.push({ bufferView: addView(nor, 34962), componentType: 5126, count: nor.length / 3, type: "VEC3" });
  const norAcc = accessors.length - 1;
  accessors.push({ bufferView: addView(idx, 34963), componentType: 5123, count: idx.length, type: "SCALAR" });
  const idxAcc = accessors.length - 1;
  materials.push({ doubleSided: true, pbrMetallicRoughness: { baseColorFactor: [...p.colour, 1], metallicFactor: 0, roughnessFactor: 0.95 } });
  primitives.push({ attributes: { POSITION: posAcc, NORMAL: norAcc }, indices: idxAcc, material: materials.length - 1 });
}

const bin = Buffer.concat(buffers);
const gltf = {
  asset: { version: "2.0", generator: "FarmTech Africa make_tree_model.js" },
  scene: 0,
  scenes: [{ nodes: [0] }],
  nodes: [{ mesh: 0, name: "pecan_tree" }],
  meshes: [{ primitives, name: "pecan_tree" }],
  materials, accessors, bufferViews,
  buffers: [{ byteLength: bin.length }],
};

let json = Buffer.from(JSON.stringify(gltf));
json = Buffer.concat([json, Buffer.alloc((4 - (json.length % 4)) % 4, 0x20)]);   // pad with spaces
const header = Buffer.alloc(12);
header.writeUInt32LE(0x46546c67, 0);                  // "glTF"
header.writeUInt32LE(2, 4);
header.writeUInt32LE(12 + 8 + json.length + 8 + bin.length, 8);
const chunk = (type, data) => { const h = Buffer.alloc(8); h.writeUInt32LE(data.length, 0); h.writeUInt32LE(type, 4); return Buffer.concat([h, data]); };

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, Buffer.concat([header, chunk(0x4e4f534a, json), chunk(0x004e4942, bin)]));
const tris = parts.reduce((s, p) => s + p.indices.length / 3, 0);
console.log(`Wrote ${OUT} (${fs.statSync(OUT).size} bytes, ${tris} triangles)`);
